def min_operations_to_one(n, a):
    @lru_cache(None)
    def dp(x):
        if x == 1:
            return 0
        res = float('inf')
        for i in range(2, int(x**0.5) + 1):
            if x % i == 0:
                res = min(res, dp(i) + dp(x // i))
        return res

    ones = sum(1 for num in a if num == 1)
    if ones > 0:
        return 0

    total_ops = 0
    for num in a:
        if num != 1:
            total_ops += dp(num)

    return total_ops if total_ops < float('inf') else -1

